import itertools

def verify():
    ok = True
    # --- C5 complement, n=5, undirected ---
    e1 = [(0, 2), (0, 3), (1, 3), (1, 4), (2, 4)]
    s1 = [frozenset(x) for x in e1]
    def ind1(sub):
        return all(frozenset((a, b)) not in s1 for a in sub for b in sub if a != b)
    # exhaustive 2^5 check: alpha must be exactly 2, no independent triple
    a1 = 0
    for k in range(6):
        for sub in itertools.combinations(range(5), k):
            if ind1(sub) and k > a1:
                a1 = k
    if a1 != 2:
        ok = False
    for sub in itertools.combinations(range(5), 3):
        if ind1(sub):
            ok = False
    if not ind1((0, 2)) or len((0, 2)) != 2:
        ok = False
    # --- directed 3-cycle, n=3 ---
    d2 = [(0, 1), (1, 2), (2, 0)]
    def ind2(sub):
        return all((a, b) not in d2 and (b, a) not in d2 for a in sub for b in sub if a != b)
    a2 = 0
    for k in range(4):
        for sub in itertools.combinations(range(3), k):
            if ind2(sub) and k > a2:
                a2 = k
    if a2 != 2:
        ok = False
    for sub in itertools.combinations(range(3), 3):
        if ind2(sub):
            ok = False
    if not ind2((0, 1)) or len((0, 1)) != 2:
        ok = False
    return ok
